package telegram

import (
	"context"
	"errors"
	"sync"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"weatherbot/internal/domain"
)

// MockSender реализует интерфейс Sender для тестирования
type MockSender struct {
	mu       sync.Mutex
	messages []string
}

func (m *MockSender) Send(ctx context.Context, chatID int64, text string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.messages = append(m.messages, text)
	return nil
}

func (m *MockSender) GetMessages() []string {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.messages
}

func (m *MockSender) MessageCount() int {
	m.mu.Lock()
	defer m.mu.Unlock()
	return len(m.messages)
}

// MockWeatherGetter реализует интерфейс WeatherGetter для тестирования
type MockWeatherGetter struct{}

func (m *MockWeatherGetter) Current(ctx context.Context, city string) (domain.Weather, error) {
	return domain.Weather{}, errors.New("mock weather error")
}

func TestHandlerSpam(t *testing.T) {
	// Создаем моки
	mockSender := &MockSender{}
	mockWeatherGetter := &MockWeatherGetter{}

	// Создаем обработчик
	handler := NewHandler(mockWeatherGetter, mockSender, nil)

	ctx := context.Background()
	chatID := int64(12345)

	// Отправляем 10 сообщений подряд
	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			handler.Handle(ctx, chatID, "Москва")
		}(i)
	}
	wg.Wait()

	// Проверяем, что было отправлено только одно сообщение "Не так быстро"
	messages := mockSender.GetMessages()
	assert.Equal(t, 1, mockSender.MessageCount(), "expected only one 'too frequent' message")

	// Проверяем, что это сообщение действительно "Не так быстро"
	assert.Equal(t, msgTooFrequent, messages[0], "expected 'too frequent' message")
}

