package telegram

import (
	"context"
	"log/slog"
	"strings"
	"testing"
	"time"

	"weatherbot/internal/domain"
)

// Тест для проверки поведения при спам-всплеске
func TestHandlerSpam(t *testing.T) {
	// Создаем фейковый провайдер погоды, который всегда возвращает успешный результат
	fakeWeather := &fakeWeather{
		w: domain.Weather{
			City:        "Москва",
			Country:     "RU",
			TempC:       12.4,
			FeelsLikeC:  9.6,
			Description: "ясно",
			Humidity:    71,
			WindSpeed:   4.2,
			WindDeg:     315,
		},
	}

	fakeSender := &fakeSender{}
	handler := NewHandler(fakeWeather, fakeSender, slog.New(slog.DiscardHandler))

	// Отправляем 10 сообщений подряд в одном чате
	for i := 0; i < 10; i++ {
		handler.Handle(context.Background(), 1, "Москва")
	}

	// Проверяем, что только первое сообщение было обработано
	// Остальные должны получить "Не так быстро"

	// В идеале должно быть:
	// 1. Ответ с погодой на первое сообщение
	// 2. 9 сообщений с "Не так быстро"

	// Но в текущей реализации все 10 будут получать "Не так быстро"

	// Считаем количество отправленных сообщений
	sentCount := len(fakeSender.sent)

	// Проверяем, что все сообщения были отправлены
	if sentCount != 10 {
		t.Errorf("Ожидалось 10 сообщений, получено %d", sentCount)
	}

	// Проверяем, что только первое сообщение содержит погоду
	weatherCount := 0
	tooFrequentCount := 0

	for _, msg := range fakeSender.sent {
		if strings.Contains(msg, "🌤") {
			weatherCount++
		} else if strings.Contains(msg, "Не так быстро") {
			tooFrequentCount++
		}
	}

	// Если все сообщения обрабатываются, то получим 10 "Не так быстро"
	// Это и есть баг - должен быть только один ответ с погодой
	if tooFrequentCount == 10 {
		t.Errorf("Все сообщения получили 'Не так быстро' - это баг! Должно быть только одно сообщение с погодой")
	}

	// Проверим, что есть хотя бы одно сообщение с погодой
	if weatherCount == 0 {
		t.Errorf("Ни одно сообщение не содержит погоды")
	}

	// Проверим, что есть только одно сообщение с погодой
	if weatherCount != 1 {
		t.Errorf("Ожидалось только одно сообщение с погодой, получено %d", weatherCount)
	}

	// Проверим, что остальные 9 - это "Не так быстро"
	if tooFrequentCount != 9 {
		t.Errorf("Ожидалось 9 сообщений 'Не так быстро', получено %d", tooFrequentCount)
	}
}

